-- 0009: Canonical trilingual faculty/program data (real durations/languages).
-- Replaces the previous sparse, AZ-only rows (name_ru/name_en were AZ copies,
-- Germany bachelor durations were wrong (4->3), Al-Farabi had a bogus Medicine row).
BEGIN;
DELETE FROM faculties WHERE university_slug IN ('giresun-universiteti', 'istanbul-universiteti', 'moskva-dovlet-universiteti', 'sankt-peterburg-universiteti', 'kiev-tibb-universiteti', 'lvov-universiteti', 'munchen-texniki-universiteti', 'berlin-universiteti', 'varshava-tibb-universiteti', 'krakov-tibb-universiteti', 'tbilisi-dovlet-tibb-universiteti', 'batumi-shota-rustaveli-universiteti', 'al-farabi-qazax-milli-universiteti', 'nazarbayev-universiteti');
COMMIT;
